import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { rememberBest } from './storage.ts';
import type { GameState } from '../game.ts';
import type { Preferences } from './storage.ts';

export interface Session {
  readonly game: GameState;
  readonly paused: boolean;
  readonly generation: number;
  readonly feedback: string;
  readonly loadNotice: string;
  readonly announcement: number;
  readonly celebration: boolean;
  readonly preferences: Preferences;
}

export const SessionNotice = {
  loaded: 'Loaded snapshot. Select Resume to continue.',
  loadedCompleted: 'Loaded completed snapshot.',
  invalidBoard: 'Invalid board code.',
  invalidSnapshot: 'Invalid snapshot.',
} as const;

export function initialSession(code: string, preferences: Preferences): Session {
  return {
    game: createGame(code),
    paused: false,
    generation: 0,
    feedback: '',
    loadNotice: '',
    announcement: 0,
    celebration: false,
    preferences,
  };
}

export function replaceGame(session: Session, game: GameState, imported: boolean): Session {
  const paused = imported && !isWon(game);
  const loadNotice = imported
    ? paused
      ? SessionNotice.loaded
      : SessionNotice.loadedCompleted
    : '';
  return {
    ...session,
    game,
    paused,
    generation: session.generation + 1,
    celebration: false,
    preferences: { ...session.preferences, size: game.size },
    // Only loads have a published status. A new deal clears the last turn result silently.
    announcement: imported ? session.announcement + 1 : session.announcement,
    feedback: loadNotice,
    loadNotice,
  };
}

export function tickSession(session: Session, generation: number, milliseconds: number): Session {
  if (session.generation !== generation || session.paused) return session;
  const game = advanceGame(session.game, milliseconds);
  return game === session.game ? session : { ...session, game };
}

export function activateSession(session: Session, index: number): Session {
  if (session.paused) return session;
  const game = activateCard(session.game, index);
  if (game === session.game) return session;
  if (game.selection.kind === SelectionKind.one) return { ...session, game };
  const won = isWon(game);
  const feedback = won
    ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
    : game.selection.kind === SelectionKind.mismatch
      ? 'No match. Cards close after a short pause.'
      : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
  const preferences = won
    ? rememberBest(session.preferences, game.size, game.moves)
    : session.preferences;
  return {
    ...session,
    game,
    feedback,
    announcement: session.announcement + 1,
    preferences,
    celebration: won,
  };
}
import { boardCode, SEED_MAX } from '../deck.ts';

const UINT32_RANGE = 2 ** 32;
const RANDOM_LIMIT = Math.floor(UINT32_RANGE / SEED_MAX) * SEED_MAX;

export function freshBoardCode(size: number, previousSeed?: number): string {
  const buffer = new Uint32Array(1);
  for (;;) {
    crypto.getRandomValues(buffer);
    const draw = buffer[0];
    if (draw === undefined || draw >= RANDOM_LIMIT) continue;
    const seed = (draw % SEED_MAX) + 1;
    if (seed !== previousSeed) return boardCode(size, seed);
  }
}
import { generateBoard } from './deck.ts';
import { SelectionKind } from './selection.ts';
import type { Board } from './deck.ts';
import type { Selection } from './selection.ts';

export const ELAPSED_MAX_MS = 359_999_999;
export const MISMATCH_MS = 800;
export const MOVES_MAX = 999_999;

export interface GameState extends Board {
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState {
  return {
    ...generateBoard(boardCode),
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

// The board reads one set per game state instead of searching the matched list for every card.
export function faceUpCards(state: Pick<GameState, 'matched' | 'selection'>): ReadonlySet<number> {
  const cards = new Set(state.matched);
  const selection = state.selection;
  if (selection.kind === SelectionKind.one) cards.add(selection.index);
  if (selection.kind === SelectionKind.mismatch) {
    cards.add(selection.first);
    cards.add(selection.second);
  }
  return cards;
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length) return state;
  if (state.matched.includes(index)) return state;
  switch (state.selection.kind) {
    case SelectionKind.closed:
      return { ...state, started: true, selection: { kind: SelectionKind.one, index } };
    case SelectionKind.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MOVES_MAX, state.moves + 1);
      if (state.deck[first] === state.deck[index]) {
        return {
          ...state,
          moves,
          matched: [...state.matched, first, index],
          selection: { kind: SelectionKind.closed },
        };
      }
      return {
        ...state,
        moves,
        selection: { kind: SelectionKind.mismatch, first, second: index, remainingMs: MISMATCH_MS },
      };
    }
    case SelectionKind.mismatch:
      return state;
    default:
      return unreachable(state.selection);
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0) return state;
  if (!state.started || isWon(state)) return state;
  const elapsedMs = Math.min(ELAPSED_MAX_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== SelectionKind.mismatch) return { ...state, elapsedMs };
  const remainingMs = state.selection.remainingMs - milliseconds;
  const selection =
    remainingMs > 0 ? { ...state.selection, remainingMs } : { kind: SelectionKind.closed };
  return { ...state, elapsedMs, selection };
}

function unreachable(value: never): never {
  throw new Error(`Unknown selection: ${String(value)}`);
}
import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}

## Features with saved records

For a feature that presents saved records, the unavailable-storage state belongs near the data it affects. The active interaction can still use its current in-memory state even though later visits cannot rely on finding that state again. When browser storage is blocked, a feature keeps working in memory and shows "Progress won't be saved on this device." where its saved records would appear. This ties the explanation to the missing persistence rather than turning it into a failure of the whole game.

The preference adapter does not yet expose a blocked-status result. `readPreferences` returns a `Preferences` value in all cases, and `writePreferences` returns `void`. Neither return type carries an availability flag or failure reason. `Game.tsx` renders no preference-storage warning; saved-record features have separate failure feedback.

The existing status display remains driven by session state. A best achieved during a visit can appear there after a failed write because it is already in `session.preferences`. A visible best is evidence of the in-memory result; persistence across a later reload needs separate evidence. [Persistence overview](persistence-overview.md) describes the data boundary.

## Three browser operations can fail independently


## Policy for result data

When the content represents records with comparable columns, its relationships need to survive reading beyond the visual arrangement. CSS alone can align text while leaving those relationships absent from the document structure. Ranked or bracket data is a table element with a caption and th scope="col" header cells. The caption identifies the collection being read, while the column headers connect each record's values to their meaning.

This is a content-specific policy. It does not make the game board a data table because it has rows and columns, and it does not require converting every compact summary to tabular markup. The distinction begins with what the content means: interactive card coordinates, a property's value and a record in an ordered result collection are different things.

No such result feature is present in `Game.tsx`. The policy applies when result data is introduced. [Native controls guide](native-controls-guide.md) discusses the broader preference for native semantics without adding another result format.

## Why the statistics are a definition list

## Existing page and future screens

`Game.tsx` currently renders one main area with an h1, deal controls, statistics, instructions, turn output, the Board and reproduction controls. It has no alternate-screen branch or screen-level h2 focus target. Replacing a deal remounts the board within that page; it does not replace the page with a different screen.

A feature that introduces a screen replacement has a different orientation problem from resetting a deck. When a feature replaces what the main area shows, focus moves to that screen's h2, which has tabindex="-1". This gives the new screen a programmatic landing place without adding that heading to ordinary Tab traversal. The current deal and load callbacks can still be understood on their own terms; they are not evidence that such a screen transition already exists.

The policy applies to the feature-level replacement described here. Expanding native details, updating statistics, closing a mismatch or displaying the completed-game paragraph does not currently create a new screen. Those operations retain the page structure and follow the existing behavior below. [Dialog policy](dialog-policy.md) covers a separate interaction with its own opening focus.

## Initial load is quiet

The hook `useBoardFocus(size)` initializes `focused` to zero. Board gives index 0 a tab index of zero and the other card buttons a tab index of minus one. This makes the first card available on entry, but no mount effect calls its focus method.

The browser's current focus therefore remains where it is at initial load. The page does not jump down to the board before a player has found Grid size or New Game. The board help paragraph describes how to enter and operate it. Its region uses `aria-describedby="board-help"` to associate those instructions with the board.

A remembered entry point is often described casually as “focus on the first card.” In this code that wording is incomplete. There is an entry point ready at the first card, while actual focus may be on the document, a deal button or another native control. Keeping those concepts separate prevents accidental mount-time focus stealing.

