          {event.phase === 'turnComplete' && <button type=\"button\" className=\"control\" onClick={() => setEvent({ ...event, phase: 'ready' })}>Next turn</button>}
          {event.phase === 'matchComplete' && <button type=\"button\" className=\"control\" onClick={() => setEvent(newMatch(event))}>Next match</button>}
          <button type=\"button\" className=\"control\" onClick={() => confirm(back)}>Leave tournament</button>
        </div>
      </>}
      {event.phase === 'playing' && <><GameStatus game={controller.session.game} best={undefined} celebration={controller.session.celebration} /><p id=\"board-help\" className=\"help\">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p><div className=\"game-result\"><p role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"><span key={controller.session.announcement}>{controller.session.feedback}</span></p></div><Board key={controller.session.generation} game={controller.session.game} activate={controller.activate} /></>}
      <Bracket tournament={event} />
    </>}
    <Exchange text={json} change={setJson} exportData={exportData} load={load} notice={notice} />
    <dialog ref={dialog} onCancel={() => { pending.current = null; }}><p>Leave this tournament?</p><button type=\"button\" className=\"control\" autoFocus onClick={() => dialog.current?.close()}>Keep playing</button><button type=\"button\" className=\"control\" onClick={() => { dialog.current?.close(); pending.current?.(); pending.current = null; }}>Leave</button></dialog>
  </main>;
}
