import { useEffect, useRef, useState } from 'react';
import { Board } from './board/Board.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import { isWon } from './game.ts';
import { useGame } from './session/use-game.ts';
import { freshBoardCode } from './session/fresh-board.ts';
import { Bracket } from './tournament/Bracket.tsx';
import { Exchange } from './tournament/Exchange.tsx';
import { decodeTournament, encodeTournament } from './tournament/format.ts';
import { readHistory, saveHistory } from './tournament/storage.ts';
import {
  nameError,
  nextMatch,
  normalizeName,
  recordResult,
  roundName,
  roundSize,
  winner,
} from './tournament/tournament.ts';
import type { Tournament as Event } from './tournament/tournament.ts';
import './tournament/tournament.css';

export function Tournament({ back }: { back(): void }) {
  const controller = useGame(true);
  const [event, setEvent] = useState<Event | null>(null);
  const [count, setCount] = useState(4);
  const [drafts, setDrafts] = useState(Array<string>(8).fill(''));
  const [error, setError] = useState('');
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const [historyState] = useState(readHistory);
  const [history, setHistory] = useState(historyState.items);
  const [blocked, setBlocked] = useState(historyState.blocked);
  const board = useRef<BoardFocus>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const pending = useRef<(() => void) | null>(null);
  const saved = useRef<Event | null>(null);
  const screen = !event
    ? 'setup'
    : event.phase === 'playing'
      ? 'playing'
      : event.phase === 'champion'
        ? 'champion'
        : 'bracket';
  useEffect(() => {
    heading.current?.focus();
  }, [screen]);
  useEffect(() => {
    if (event?.phase === 'playing' && isWon(controller.session.game)) {
      setEvent(
        recordResult(event, {
          moves: controller.session.game.moves,
          elapsedMs: controller.session.game.elapsedMs,
        }),
      );
    }
  }, [event, controller.session.game]);
  useEffect(() => {
    if (!event || event.phase !== 'champion' || saved.current === event) return;
    saved.current = event;
    setHistory((previous) => {
      const updated = [event, ...previous].slice(0, 10);
      if (!saveHistory(updated)) setBlocked(true);
      return updated;
    });
  }, [event]);
  function confirm(action: () => void) {
    if (event && event.phase !== 'champion') {
      pending.current = action;
      dialog.current?.showModal();
    } else action();
  }
  function newMatch(current: Event): Event {
    const size = roundSize(current.names.length, current.matches.length);
    let code = freshBoardCode(size);
    while (current.matches.some((match) => match.boardCode === code)) code = freshBoardCode(size);
    return nextMatch(current, code);
  }
  function start() {
    const names = drafts.slice(0, count).map(normalizeName);
    const message = nameError(names);
    if (message) {
      setError(message);
      return;
    }
    setError('');
    setEvent(newMatch({ names, matches: [], phase: 'ready' }));
  }
  function startTurn() {
    if (!event) return;
    const match = event.matches[event.matches.length - 1]!;
    controller.loadBoard(match.boardCode);
    setEvent({ ...event, phase: 'playing' });
  }
  function exportData() {
    const snapshot =
      event?.phase === 'playing' && !isWon(controller.session.game)
        ? controller.exportSnapshot()
        : null;
    setJson(encodeTournament({ tournament: event, snapshot }));
    setNotice('Tournament exported.');
  }
  function load() {
    const result = decodeTournament(json);
    if (!result.data) {
      setNotice(result.error ?? 'Invalid tournament.');
      return;
    }
    const data = result.data;
    confirm(() => {
      if (data.snapshot) {
        controller.loadSnapshot(data.snapshot);
        controller.resume();
      }
      setEvent(data.tournament);
      setNotice('Tournament loaded.');
    });
  }
  const match = event?.matches[event.matches.length - 1];
  const player = match?.players[match.results.length];
  return (
    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 ref={heading} tabIndex={-1}>
        {screen === 'champion'
          ? 'Tournament complete'
          : screen === 'playing'
            ? 'Tournament turn'
            : 'Tournament'}
      </h2>
      {!event ? (
        <>
          <div className="tournament-section">
            <label htmlFor="players">Players</label>{' '}
            <select
              className="control"
              id="players"
              value={count}
              onChange={(e) => setCount(Number(e.currentTarget.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
            <div className="tournament-fields">
              {drafts.slice(0, count).map((name, index) => (
                <label key={index}>
                  Player {index + 1}
                  <input
                    className="control"
                    value={name}
                    onChange={(e) => {
                      const value = e.currentTarget.value;
                      setDrafts((old) => old.map((item, i) => (i === index ? value : item)));
                    }}
                  />
                </label>
              ))}
            </div>
            {error && <p role="alert">{error}</p>}
            <button type="button" className="control" onClick={start}>
              Start tournament
            </button>
          </div>
          <section className="tournament-section">
            <h3>Past tournaments</h3>
            {blocked && <p>Progress won't be saved on this device.</p>}
            {history.length === 0 ? (
              <p>No past tournaments.</p>
            ) : (
              history.map((item, index) => (
                <details key={index}>
                  <summary>
                    Champion: {item.names[winner(item.matches[item.matches.length - 1]!)]}
                  </summary>
                  <Bracket tournament={item} />
                </details>
              ))
            )}
          </section>
          <button type="button" className="control" onClick={back}>
            Back to game
          </button>
        </>
      ) : (
        <>
          {event.phase === 'champion' ? (
            <>
              <p>Champion: {event.names[winner(match!)]}</p>
              <button type="button" className="control" onClick={back}>
                Back to game
              </button>
            </>
          ) : (
            <>
              <p>Round: {roundName(roundSize(event.names.length, event.matches.length - 1))}</p>
              {(event.phase === 'ready' || event.phase === 'playing') && (
                <p>Now playing: {event.names[player!]}</p>
              )}
              <div className="tournament-actions">
                {event.phase === 'ready' && (
                  <button type="button" className="control" onClick={startTurn}>
                    Start turn
                  </button>
                )}
                {event.phase === 'turnComplete' && (
                  <button
                    type="button"
                    className="control"
                    onClick={() => setEvent({ ...event, phase: 'ready' })}
                  >
                    Next turn
                  </button>
                )}
                {event.phase === 'matchComplete' && (
                  <button
                    type="button"
                    className="control"
                    onClick={() =>
                      setEvent(
                        event.matches.length === event.names.length - 1
                          ? { ...event, phase: 'champion' }
                          : newMatch(event),
                      )
                    }
                  >
                    Next match
                  </button>
                )}
                <button type="button" className="control" onClick={() => confirm(back)}>
                  Leave tournament
                </button>
              </div>
            </>
          )}
          {event.phase === 'playing' && (
            <>
              <GameStatus
                game={controller.session.game}
                best={undefined}
                celebration={controller.session.celebration}
              />
              <p id="board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or
                Space reveals a card.
              </p>
              <div className="game-result">
                <p role="status" aria-live="polite" aria-atomic="true">
                  <span key={controller.session.announcement}>{controller.session.feedback}</span>
                </p>
              </div>
              <Board
                key={controller.session.generation}
                game={controller.session.game}
                activate={controller.activate}
                ref={board}
              />
            </>
          )}
          <Bracket tournament={event} />
        </>
      )}
      <Exchange text={json} change={setJson} exportData={exportData} load={load} notice={notice} />
      <dialog
        ref={dialog}
        onCancel={() => {
          pending.current = null;
        }}
      >
        <p>Leave this tournament?</p>
        <button type="button" className="control" autoFocus onClick={() => dialog.current?.close()}>
          Keep playing
        </button>
        <button
          type="button"
          className="control"
          onClick={() => {
            dialog.current?.close();
            pending.current?.();
            pending.current = null;
          }}
        >
          Leave
        </button>
      </dialog>
    </main>
  );
}

