    if (!match) return;
    if (event.phase === '"'ready') announce("'`Now playing: ${event.names[match.players[match.results.length]!]}`);
    if (event.phase === '"'champion') announce("'`Champion: ${event.names[winner(match)]}`);
  }, [event]);
  return { announcement, announce };
}
